import{_ as t,o as s,c as o,a2 as n}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"Sessions","description":"","frontmatter":{},"headers":[],"relativePath":"sessions.md","filePath":"sessions.md","lastUpdated":1794034150000}'),a={name:"sessions.md"};function r(i,e,d,h,l,c){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h1><p>A session is one coding agent working in its own pod in your cluster, with its own workspace, network policy and credentials. This page covers creating a session, the choices in the <strong>New session</strong> dialog, and what you can change while it runs.</p><p><strong>Edition:</strong> Community · <strong>Who:</strong> the session owner. People a session is <a href="/docs/sharing">shared</a> with (Enterprise) can watch or type, but cannot change its settings.</p><h2 id="session-modes" tabindex="-1">Session modes <a class="header-anchor" href="#session-modes" aria-label="Permalink to &quot;Session modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>What it does</th><th>Typical use</th></tr></thead><tbody><tr><td><strong>Interactive</strong></td><td>You watch the agent and reply to it, in the <a href="/docs/workspace">Workspace</a> or the terminal.</td><td>Pairing, exploratory work</td></tr><tr><td><strong>Autonomous</strong></td><td>Works through the <strong>Task</strong> on its own and ends when it is done.</td><td>A well-described task you hand off</td></tr><tr><td><strong>Scheduled</strong></td><td>Runs the task on a cron schedule (UTC) as a Kubernetes CronJob. Each run works like an autonomous session.</td><td>Nightly dependency updates, reports</td></tr></tbody></table><p>A scheduled session&#39;s cron expression can be changed later in <strong>Edit session</strong>; the dialog shows the next run in UTC. Schedule changes apply to future runs and leave a run in progress alone. To change a scheduled session&#39;s agent, billing, policy or runtime settings, delete and recreate it.</p><h2 id="agent-and-billing" tabindex="-1">Agent and billing <a class="header-anchor" href="#agent-and-billing" aria-label="Permalink to &quot;Agent and billing&quot;">​</a></h2><p>Choose the agent per session: <strong>Claude</strong> (Claude Code), <strong>Codex</strong>, <strong>Cursor</strong>, <strong>OpenClaw</strong> or <strong>OpenCode</strong>. An administrator can restrict which agents are offered (Enterprise, see <a href="/docs/admin">Administration</a>).</p><p><strong>Billing</strong> is independent of the agent and of the mode:</p><ul><li><strong>Subscription</strong> uses your provider login. See <a href="/docs/provider-login">Provider login</a> for signing in and for choosing among several stored accounts.</li><li><strong>API key</strong> uses a key stored under <strong>Settings → Credentials</strong>. Only that key is given to the agent process. For OpenClaw you also pick which stored key it uses.</li><li><strong>Own endpoint</strong> points Claude, Codex or OpenCode at a self-hosted model server: enter the endpoint URL and the model name. The dialog names the protocol the agent expects. Cursor and OpenClaw cannot use an own endpoint.</li></ul><p>Below billing, <strong>Model</strong> sets the model the session starts on and lists the models the chosen account offers. See <a href="/docs/models">Choosing a model</a>.</p><div class="warning custom-block"><p class="custom-block-title">Credentials are visible to the agent</p><p>Whatever credential a session gets is readable by the agent and the tools it runs. Run only repositories and prompts you trust while credentials are present.</p></div><h2 id="the-new-session-dialog" tabindex="-1">The New session dialog <a class="header-anchor" href="#the-new-session-dialog" aria-label="Permalink to &quot;The New session dialog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Title</strong>, <strong>Description</strong></td><td>The description tells the other agents of the project what this one is for.</td></tr><tr><td><strong>Interface</strong></td><td><strong>Workspace</strong> (conversation view) or <strong>Terminal</strong> (the agent&#39;s own console). The default comes from <strong>Settings → Interface</strong>.</td></tr><tr><td><strong>Task</strong></td><td>Required for Autonomous and Scheduled; an optional first message for an Interactive Workspace session.</td></tr><tr><td><strong>System prompt</strong></td><td>Standing rules appended to the agent&#39;s own instructions.</td></tr><tr><td><strong>Project</strong></td><td>Puts the session in a <a href="/docs/projects">project</a>; <strong>New project…</strong> creates one on the spot.</td></tr><tr><td><strong>Secrets</strong></td><td>Which stored <a href="/docs/secrets">secrets</a> this session receives.</td></tr><tr><td><strong>Repositories</strong></td><td>One or more repositories to clone into the workspace, and which <a href="/docs/git">git tokens</a> the session gets.</td></tr><tr><td><strong>Auto-delete</strong></td><td>Delete the session on its own after a number of hours or days, counted from its start or from its last activity.</td></tr><tr><td><strong>Advanced</strong></td><td>Tool policy, <a href="/docs/mcp-servers">MCP servers</a>, container image, resources, <strong>Run as root</strong>, <strong>Auto approve</strong>.</td></tr></tbody></table><h3 id="tool-policy-for-unattended-sessions" tabindex="-1">Tool policy for unattended sessions <a class="header-anchor" href="#tool-policy-for-unattended-sessions" aria-label="Permalink to &quot;Tool policy for unattended sessions&quot;">​</a></h3><p>Under <strong>Advanced</strong>, Autonomous and Scheduled sessions take an allow list: built-in tools and patterns, full MCP tool names, and shell commands (exact commands for Claude, command prefixes for Codex and the others; Cursor has no shell list). Empty fields allow nothing in that category.</p><p>When <strong>Auto approve</strong> is on, the allow list is a head start, not a boundary: a tool that is not on it becomes an approval request, which auto approve then answers. With auto approve off, a tool outside the allow list waits for your approval in the web app or in <a href="/docs/chat">chat</a>; if nobody answers before the wait ends, it is denied. Nobody watches an unattended session, so tick <strong>Auto approve</strong> when it should not stop on such a request. Sessions created through the API or an MCP client without an explicit choice get auto approve on for Autonomous and Scheduled mode. See <a href="/docs/auto-approve">Auto approve</a>.</p><p>The hub&#39;s own tools that only read the session&#39;s state or clean up after it do not need to be on the allow list: <code>agent_inbox</code>, <code>agents_list</code>, <code>session_list</code>, <code>session_get</code>, <code>session_wait</code>, <code>container_list</code>, <code>container_logs</code>, <code>container_stop</code>, <code>secrets_list</code>, <code>account_status</code> and <code>port_list</code>. A session that may start a helper container can therefore always stop it again and read its own messages. Tools that let a session do more (<code>session_create</code>, <code>container_run</code>, <code>secret_request</code>, <code>port_request</code>, <code>agent_send</code> and the others) still need an entry. A block under <strong>MCP security</strong> in the <a href="/docs/sharing">Share dialog</a> applies to all of them.</p><p>An <code>mcp__…</code> name in the general tool list counts for every agent, as it does in the MCP tool list.</p><h3 id="container-image-and-root-mode" tabindex="-1">Container image and root mode <a class="header-anchor" href="#container-image-and-root-mode" aria-label="Permalink to &quot;Container image and root mode&quot;">​</a></h3><p><strong>Container image</strong> runs the agent inside your own toolchain image; the agent runtime and terminal transport are copied in at start. The image must be glibc-based (Debian, Ubuntu, Fedora and similar); Alpine is not supported.</p><p><strong>Run as root</strong> lets the agent install system packages (apt, <code>npm -g</code>). The pod stays unprivileged otherwise. An operator can switch root sessions off for the whole instance (<code>agent.allowRootSessions</code>). Without root, the agent&#39;s root filesystem is read-only: it can write to its workspace, <code>$HOME</code> and <code>/tmp</code>.</p><h3 id="cpu-and-memory" tabindex="-1">CPU and memory <a class="header-anchor" href="#cpu-and-memory" aria-label="Permalink to &quot;CPU and memory&quot;">​</a></h3><p><strong>CPU request</strong> and <strong>Memory request</strong> are reserved on the node. <strong>CPU limit</strong> and <strong>Memory limit</strong> cap the session: above the limit CPU is throttled and the agent is stopped for memory. Memory is given in <code>Mi</code> or <code>Gi</code>. An empty limit means the instance default; the operator sets the defaults and the highest limit a session may ask for (see <a href="/docs/chart-values">Chart values</a>). Values that make no sense, such as <code>10m</code> of memory, are refused when you save.</p><h2 id="changing-a-running-session" tabindex="-1">Changing a running session <a class="header-anchor" href="#changing-a-running-session" aria-label="Permalink to &quot;Changing a running session&quot;">​</a></h2><p>Open <strong>Edit session</strong> from the session list or the session header.</p><ul><li><strong>Title</strong>, <strong>Auto approve</strong> and <strong>Auto-delete</strong> apply at once.</li><li><strong>Switch account automatically at usage limit</strong> applies at once (see <a href="/docs/provider-login#usage-limits-and-account-failover">Provider login</a>).</li><li><strong>Image</strong>, <strong>Run as root</strong>, resources and the <strong>System prompt</strong> apply at the next resume. For a change that needs it, the dialog offers <strong>Restart now</strong>: the session is paused and resumed, its state is saved and the conversation continues, but a turn in progress is interrupted.</li><li>Repositories, git tokens, MCP servers and secret grants can be changed as well; the dialog says when a change needs a restart.</li></ul><p><strong>Pause</strong> stops the pod and keeps the conversation; <strong>Resume</strong> starts a new pod and continues it. The workspace directory itself is not kept across a pause: push your work with git or save files to the session&#39;s <a href="/docs/files">files</a>.</p><h2 id="duplicate-a-session" tabindex="-1">Duplicate a session <a class="header-anchor" href="#duplicate-a-session" aria-label="Permalink to &quot;Duplicate a session&quot;">​</a></h2><p><strong>Duplicate session</strong> copies a session&#39;s configuration into a new, independent session: agent, billing, project, repositories, policy, resources and, if you tick them, the MCP configuration and saved MCP servers. It does not copy the conversation, files, sharing settings or browser cookies.</p><h2 id="continue-an-autonomous-run-interactively" tabindex="-1">Continue an autonomous run interactively <a class="header-anchor" href="#continue-an-autonomous-run-interactively" aria-label="Permalink to &quot;Continue an autonomous run interactively&quot;">​</a></h2><p>When an autonomous run has finished or stopped, the session offers <strong>Continue it interactively?</strong> with <strong>Open workspace</strong> or <strong>Open terminal</strong>, and <strong>Keep auto-approve</strong> to keep approving tools without asking. Claude, Codex and OpenCode continue the same conversation. Cursor and OpenClaw start a new conversation in the same workspace: the files stay, the chat history does not.</p><h2 id="runtime-updates" tabindex="-1">Runtime updates <a class="header-anchor" href="#runtime-updates" aria-label="Permalink to &quot;Runtime updates&quot;">​</a></h2><p>After an upgrade, sessions started from an older runtime image are marked <strong>outdated image</strong>. <strong>Update now</strong> restarts the session on the current image; it is paused and resumed like a restart.</p><p>An operator can turn on automatic updates for idle sessions (<code>agent.autoUpdateRuntimeImages</code>, default off). Per session, <strong>Edit session → Automatic runtime image updates</strong> chooses <strong>Deployment default</strong>, <strong>On when safe</strong> or <strong>Off</strong>. Automatic updates only replace a session when its runtime confirms that the agent has finished its turn; sessions with a custom image keep that image.</p><h2 id="sessions-that-delete-themselves" tabindex="-1">Sessions that delete themselves <a class="header-anchor" href="#sessions-that-delete-themselves" aria-label="Permalink to &quot;Sessions that delete themselves&quot;">​</a></h2><p><strong>Auto-delete</strong> removes a session after the time you set, counted <strong>after start</strong> or <strong>after last activity</strong> (opening it, typing or sending it a message restarts the countdown). The remaining time is shown wherever the session is listed. The minimum is five minutes and the maximum 365 days. Deleting a session also deletes its stored state and files.</p><h2 id="when-a-session-cannot-start" tabindex="-1">When a session cannot start <a class="header-anchor" href="#when-a-session-cannot-start" aria-label="Permalink to &quot;When a session cannot start&quot;">​</a></h2><p>The session list and the Workspace show why a session cannot start in plain words: a failed clone (naming the repository), an image that cannot be pulled, a pod that cannot be scheduled, a refused resource request, or the agent&#39;s own last output when it exits with an error (for example an expired login).</p><p>When the initial clone fails because a host cannot be resolved or reached, it is retried with increasing waits for up to five minutes before the session fails with <em>Network error: could not reach …</em>. Errors such as <em>repository not found</em>, denied authentication or an unknown branch fail at once. A connection that hangs instead of failing is not covered by the retry. Fix the repository in <strong>Edit session</strong> and resume.</p><h2 id="helper-containers" tabindex="-1">Helper containers <a class="header-anchor" href="#helper-containers" aria-label="Permalink to &quot;Helper containers&quot;">​</a></h2><p>An agent can start helper containers next to its session, for example a database for the migration it is writing. They run in a namespace of their own for that session, are never more privileged than the session, are subject to its network policy, and are removed when the session is paused or deleted. The agent manages them with built-in tools; see <a href="/docs/session-tools">Built-in tools inside a session</a>.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/docs/projects">Projects</a>: grouping, ordering and moving sessions</li><li><a href="/docs/workspace">Workspace</a>: the conversation view</li><li><a href="/docs/questions-approvals">Questions and approvals</a></li><li><a href="/docs/sharing">Sharing</a> (Enterprise)</li></ul>',44)])])}const p=t(a,[["render",r]]);export{u as __pageData,p as default};
